batterySource:
// generic-rag-chunking P-009 R-25 live battery: plans:search (working-tree
// handler, default result count) against the live operator DB after the plans
// chunk sync + embed. Sample: N plans of harness papercusp whose content is over
// 6,000 characters, taken in md5(plan_slug) order (a fixed pseudo-random order,
// no hand-picking). Query: one sentence from the part of the plan past its first
// 2,000 characters that the capped windows still cover (same rule for every plan),
// whose opening words do not occur in the first 2,000 characters. Records whether
// the target plan comes back within the default count, its rank, the matched
// section, and — so a miss can be told apart from a missing row — the target's
// rank by its own (parent) vector alone and by its best chunk alone.
export {};
const base = 'file://~/papercupai-workspace/papercusp/packages/operator-core/lib/';
const { installSearchDefaults } = await import(base + 'search/configure-search-defaults.ts');
const { buildQueryEmbedderResolved } = await import(base + 'agent-tools/search/embedder.ts');
const { PLANS_CHUNK_SURFACE } = await import(base + 'search/chunks/registry.ts');
const plansSearch = (await import(base + 'agent-tools/plans/search.ts')).default;
const { getOrgPg } = await import('@papercusp/db-org');
installSearchDefaults();

const CUT = 2000;
const N = Number(process.env.N ?? 10);
const HARNESS = 'papercusp';
const WS = 'papercusp-workspace';
const sp = PLANS_CHUNK_SURFACE.splitter as { size: number; overlap: number };
const covered = sp.size + (PLANS_CHUNK_SURFACE.maxChunks! - 1) * (sp.size - sp.overlap);
const resolved = await buildQueryEmbedderResolved({ acquireBudgetMs: 20_000 });
if (!resolved) throw new Error('no query embedder');
const { sql } = getOrgPg();

const plans = await sql.unsafe<Array<{ plan_slug: string; content: string }>>(
  `SELECT plan_slug, content FROM harness_shared.harness_plans
    WHERE workspace_id = $1 AND harness_slug = $2 AND template_slug IS NULL AND length(content) > 6000
    ORDER BY md5(plan_slug) LIMIT $3`,
  [WS, HARNESS, N * 3],
);

const rows: Array<Record<string, unknown>> = [];
for (const p of plans) {
  if (rows.filter((r) => !r.skipped).length >= N) break;
  const head = p.content.slice(0, CUT).toLowerCase();
  const region = p.content.slice(CUT, Math.min(p.content.length, covered) - 50);
  const sentences = region
    .split(/(?<=[.!?])\s+|\n+/)
    .map((s) => s.replace(/[`*_#>|[\]()]/g, ' ').replace(/\s+/g, ' ').trim())
    .filter((s) => s.split(' ').length >= 8 && s.length <= 220 && !head.includes(s.toLowerCase().slice(0, 40)));
  const query = sentences[Math.floor(sentences.length * 0.6)];
  if (!query) {
    rows.push({ plan: p.plan_slug, skipped: 'no usable sentence' });
    continue;
  }
  const vec = `[${(await resolved.embed(query)).join(',')}]`;
  const [parentRank] = await sql.unsafe<Array<{ rank: number }>>(
    `WITH r AS (SELECT plan_slug, row_number() OVER (ORDER BY embedding <=> $3::vector) AS rank
                  FROM harness_shared.harness_plans
                 WHERE workspace_id = $1 AND harness_slug = $2 AND embedding IS NOT NULL AND template_slug IS NULL)
     SELECT rank::int FROM r WHERE plan_slug = $4`,
    [WS, HARNESS, vec, p.plan_slug],
  );
  const [chunkRank] = await sql.unsafe<Array<{ rank: number; idx: number }>>(
    `WITH r AS (SELECT parent_key, chunk_idx, row_number() OVER (ORDER BY embedding <=> $2::vector) AS rank
                  FROM harness_shared.text_chunks
                 WHERE surface = 'plans' AND embedding IS NOT NULL AND parent_key[1] = $1 AND parent_key[2] = $3)
     SELECT rank::int, chunk_idx AS idx FROM r WHERE parent_key[3] = $4 ORDER BY rank LIMIT 1`,
    [WS, vec, HARNESS, p.plan_slug],
  );
  const res = (await plansSearch.handler({ query } as never, { harnessSlug: HARNESS, isSuperuser: true } as never)) as {
    content: Array<{ text: string }>;
  };
  const payload = JSON.parse(res.content[0]!.text) as {
    hits: Array<{ plan: string; matchedSection?: string }>;
    semantic?: unknown;
  };
  const i = payload.hits.findIndex((h) => h.plan === p.plan_slug);
  rows.push({
    plan: p.plan_slug,
    chars: p.content.length,
    queryOffset: p.content.indexOf(query.split(' ').slice(0, 4).join(' ')),
    query,
    hits: payload.hits.length,
    returned: i >= 0,
    rank: i + 1,
    matchedSection: i >= 0 ? (payload.hits[i]!.matchedSection ?? null) : null,
    parentVectorRank: parentRank?.rank ?? null,
    bestChunkRankWithinPlanChunks: chunkRank?.rank ?? null,
    bestChunkIdx: chunkRank?.idx ?? null,
    semantic: payload.semantic ?? null,
  });
}
for (const r of rows) console.log('ROW', JSON.stringify(r));
const done = rows.filter((r) => !r.skipped);
console.log(
  'SUMMARY',
  JSON.stringify({
    at: new Date().toISOString(),
    n: done.length,
    returned: done.filter((r) => r.returned).length,
    withSection: done.filter((r) => r.matchedSection).length,
    parentVectorInTop20: done.filter((r) => typeof r.parentVectorRank === 'number' && (r.parentVectorRank as number) <= 20).length,
  }),
);
process.exit(0);
